/-- Encode the two spin values used in (1.1) as real numbers. -/
def talagrandPaper_spin {n : ℕ} (σ : Fin n → Bool) (i : Fin n) : ℝ :=
  if σ i then 1 else -1

/-- The product of the spins at a site, with each Boolean encoding a sign. -/
def talagrandPaper_siteSpinProduct (site : Bool × Bool) : Int :=
  if site.1 == site.2 then 1 else -1

/-- The integer numerator of the overlap in (1.4), summed over the sites. -/
def talagrandPaper_overlapNumerator (sites : List (Bool × Bool)) : Int :=
  (sites.map talagrandPaper_siteSpinProduct).sum
